            aWandererH = aWandererH ^ ((RotL64(aScatter, 41U) + aOrbiterE) + RotL64(aOrbiterG, 13U));
            aWandererB = aWandererB + ((((RotL64(aPrevious, 13U) + RotL64(aOrbiterE, 57U)) + aOrbiterB) + RotL64(aCarry, 39U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 30U) + aOrbiterA) + RotL64(aOrbiterC, 35U));
            aWandererA = aWandererA + ((RotL64(aScatter, 57U) + aOrbiterJ) + RotL64(aOrbiterK, 27U));
