            //
            aOrbiterI = ((aWandererG + RotL64(aPrevious, 41U)) + RotL64(aCarry, 53U)) + 0xD579C2D988287379ULL;
            aOrbiterB = (aWandererJ + RotL64(aIngress, 35U)) + 0xDD44471C1146EF40ULL;
            aOrbiterD = ((aWandererB + RotL64(aCross, 29U)) + 0x61B20E69465C5626ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterH = ((aWandererD + RotL64(aScatter, 13U)) + RotL64(aCarry, 37U)) + 0x69B9FB32518D38B9ULL;
            aOrbiterK = ((aWandererK + RotL64(aIngress, 51U)) + 0xF658936EE512F42EULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterE = (aWandererA + RotL64(aScatter, 57U)) + 0x5C0A4B72ECE3C8CDULL;
            aOrbiterC = ((aWandererF + RotL64(aCross, 4U)) + RotL64(aCarry, 5U)) + 0xF31738AC91C8859BULL;
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x38CEE030E1C94911ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x2CE463493C93F5BCULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB0466C5A2F4A9561ULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xEA33D6FCC8DBE1E4ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0xED84DC3C26C57C70ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xA84EEF34D308FA09ULL), 27U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0xEF1771286C87D5A7ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x852B6AF40EBB60A4ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x5D099086825307D9ULL), 21U);
