            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x84975D65D071FCFAULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x3433FA61E868DE1BULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 14U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x431B64752410AF29ULL), 53U);
