            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xE93A686FB6DBC95EULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xCC23FB52D1060E4BULL;
            aOrbiterK = RotL64((aOrbiterK * 0x79EC55F6612921EFULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x6CD3EA7713957E05ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xE1E1CC84CFED23A1ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x5560E37CC68613DFULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0xBADDC3D589B48479ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0xFCAFB9DE84F4C2F6ULL;
