            aWandererK = aWandererK ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterC, 51U)) + aOrbiterB) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1]);
