            aOrbiterH = (aWandererJ + RotL64(aScatter, 43U)) + 0x086D76216D5ECCC6ULL;
            aOrbiterA = ((aWandererE + RotL64(aPrevious, 27U)) + 0x359E22CCFC1D1034ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
