            aOrbiterH = ((aWandererF + RotL64(aCross, 21U)) + RotL64(aCarry, 27U)) + 0x9A54CEA0C4111040ULL;
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 53U)) + 0x8A3B7C12607BEF3AULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 5U)) + RotL64(aCarry, 53U)) + 0xA2A736A0E3BDC0CDULL;
            aOrbiterF = ((aWandererK + RotL64(aIngress, 28U)) + 0xA1B3911E34824747ULL) + aTwistOrbiterAssignSaltF[((aIndex + 10U)) & S_SALT1];
