            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 6681U)) & S_BLOCK1], 39U) ^ RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 1831U)) & S_BLOCK1], 47U));
            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 1649U)) & W_KEY1], 30U) ^ RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 3279U)) & S_BLOCK1], 5U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCarry, 53U) + RotL64(aIngress, 12U)) ^ (RotL64(aCross, 41U) ^ RotL64(aPrevious, 29U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterB = (aWandererH + RotL64(aIngress, 27U)) + 0x6CE77533895B0F6AULL;
            aOrbiterD = (aWandererD + RotL64(aPrevious, 11U)) + 0xD749361B196CE761ULL;
            aOrbiterG = (aWandererK + RotL64(aCross, 3U)) + 0xE59774362102D190ULL;
            aOrbiterF = (((aWandererI + RotL64(aScatter, 57U)) + RotL64(aCarry, 5U)) + 0x8F351506E0CFC9ACULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterE = (aWandererJ + RotL64(aIngress, 43U)) + 0xB70FC47ABCECDA6FULL;
            aOrbiterA = ((aWandererG + RotL64(aPrevious, 51U)) + RotL64(aCarry, 35U)) + 0xBBD1D132DDB7D125ULL;
            aOrbiterI = ((aWandererF + RotL64(aCross, 20U)) + 0x4C4F5D94D99C7DDBULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aScatter, 53U)) + 0x39314DFDA0550F82ULL;
            aOrbiterJ = (aWandererA + RotL64(aIngress, 35U)) + 0x73029D74B74902D7ULL;
            aOrbiterK = ((aWandererE + RotL64(aCross, 29U)) + RotL64(aCarry, 13U)) + 0x0A538585D2BF9D0AULL;
            aOrbiterC = (aWandererC + RotL64(aPrevious, 18U)) + 0xA1C46E8F592318D9ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xC98BCD6D3D7033D0ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0xC1EAA413B15F8483ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xDD6375CFDA797887ULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xA5B3C252831EDDB5ULL;
