            aOrbiterE = RotL64((aOrbiterE * 0x0254F2B0E63D1853ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x925227D2FA60D20CULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x694C4DD8603C6B17ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x83F5B12FAA15D38BULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xA383267418D6BC9AULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x6235A416929EC11CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x7485F948C2ABCDA1ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0xEA1697354D271C61ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xEC77CE82D4F883C7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x4A37E555A6A22147ULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0x6515D4ABC07B284EULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x7A06292FCE199862ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xCFAD7473D4372B19ULL), 35U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x8CEF8E5E57BE263BULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 20U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x6C04975817CAEB7AULL;
            aOrbiterH = RotL64((aOrbiterH * 0x42E5DEA375E4946BULL), 43U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x06B36B91D04058E9ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x3BAE18AAB8F61431ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x93A71EBF899076E3ULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0xA161A7EDF2B103F1ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x53A7F79E8A093B51ULL;
