            aOrbiterD = (aWandererB + RotL64(aIngress, 14U)) + 0x4C06AD498FB3E837ULL;
            aOrbiterC = (aWandererD + RotL64(aCross, 3U)) + 0x906F303B780CC649ULL;
            aOrbiterJ = (aWandererE + RotL64(aPrevious, 39U)) + 0x347B1A6BB5C37621ULL;
            aOrbiterK = ((aWandererF + RotL64(aScatter, 35U)) + 0xFBB5CE93BB745CAEULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterB = ((aWandererJ + RotL64(aPrevious, 57U)) + RotL64(aCarry, 11U)) + 0x3932C57A6E1E1BB7ULL;
            aOrbiterE = (aWandererG + RotL64(aCross, 47U)) + 0x8F120885AF049D0FULL;
