            aOrbiterH = ((aWandererH + RotL64(aIngress, 43U)) + 0x8441C4884816E4BEULL) + aKeyRotateOrbiterAssignSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterA = (aWandererC + RotL64(aPrevious, 23U)) + 0x103D39D4270CA1D8ULL;
            aOrbiterG = ((aWandererA + RotL64(aCross, 41U)) + RotL64(aCarry, 37U)) + 0x6BAEF5C999885D7BULL;
