            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x20E435B3E53D6178ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x93B190AA73A13E3FULL;
            aOrbiterD = RotL64((aOrbiterD * 0xAFE55104D55E7589ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x0BA3C985D7A0BC7EULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x88A95E69C97A9425ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4E9F1E46308D18ADULL), 21U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0x1E6B1C971B26A138ULL) + aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x771C21226B6F0321ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x298AA1257246492DULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xA62D094BE20587C7ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0xF4E3CA8A7DE4CAFBULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 19U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xBFBC3F695F025437ULL), 39U);
