            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x58CA87A330534C20ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xB22DD102CA2E9C99ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1E2AD6F8DE1C2341ULL), 41U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x54DE6C7854B949C2ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x5E9A605869DBCFC9ULL;
