            aWandererG = aWandererG + ((((RotL64(aCross, 21U) + aOrbiterK) + RotL64(aOrbiterD, 53U)) + RotL64(aCarry, 35U)) + aKeySpawnWandererUpdateSaltC[((aIndex + 13U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterA, 3U)) + aOrbiterI);
