            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0x05260A68BF42F5F7ULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 14U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x4AA124DD741E6FBCULL;
