            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0xC83D6892652A94F1ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x8A04E73CACA4E3CCULL) ^ aKeySpawnOrbiterUpdateSaltF[((aIndex + 19U)) & S_SALT1];
